const seen = new Set();
const inputs = [0, -0, NaN, Number("x"), "0", 0 * -1];

for (const input of inputs) {
  seen.add(input);
}

console.log(seen.size);
console.log(seen.has(-0), seen.has("NaN"));
console.log(inputs.indexOf(NaN), inputs.indexOf(-0));
